        {(p.cs&&Object.keys(p.cs).length>0)&&<div style={{marginBottom:10}}><div style={{fontSize:11,color:"#a78bfa",fontWeight:700,marginBottom:2}}>CAREER STATS • {p.cs.seas||1} SEASONS</div><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(52px,1fr))",gap:3}}>{Object.entries(p.cs).filter(([k,v])=>k!=="seas"&&typeof v==="number"&&v>0).map(([k,v])=>(<div key={k} style={{background:C.bg,borderRadius:4,padding:"4px 3px",textAlign:"center"}}><div style={{fontSize:9,color:C.mt,letterSpacing:.3}}>{sL(k)}</div><div style={{fontSize:14,fontWeight:700,color:"#c4b5fd"}}>{fm(v)}</div></div>))}</div></div>}
