        {/* INNO I73: confidence/morale mini-history sparkline */}
        {(()=>{const _confHist=(p?.confHistory||[]).slice(-6);if(_confHist.length<2)return null;const _max=Math.max(100,..._confHist),_min=Math.min(0,..._confHist);const _range=_max-_min||1;return <div style={{marginTop:4}}><div style={{fontSize:10,color:'#334155',letterSpacing:1,marginBottom:2}}>MORALE TREND</div><svg width="80" height="18" style={{overflow:'visible'}}>{_confHist.map((v,i)=>{if(i===0)return null;const x1=(i-1)*80/(_confHist.length-1),x2=i*80/(_confHist.length-1);const y1=16-((_confHist[i-1]-_min)/_range)*14,y2=16-((v-_min)/_range)*14;return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={v>=70?'#22c55e':v>=40?'#f59e0b':'#ef4444'} strokeWidth="1.5"/>;})}</svg></div>;})()}
        {/* v27 I42: Trade value tag + snap count + loyalty */}
        {(()=>{const _tv=Math.round(p.ovr*1.5+(30-p.age)*2+(p.contract||0)*5-(p.salary||0)/3);return(<div style={{display:'flex',gap:6,alignItems:'center',marginBottom:6,flexWrap:'wrap'}}><span style={{fontSize:10,background:'#164e63',color:'#67e8f9',borderRadius:3,padding:'2px 6px',fontWeight:700}}>Value {_tv}</span>{(p.snaps||0)>0&&<span style={{fontSize:10,background:'#1e293b',color:'#94a3b8',borderRadius:3,padding:'2px 6px'}}>⚡ {p.snaps} snaps</span>}{p.loyal&&<span style={{fontSize:10,background:'#7c3aed',color:'#ddd6fe',borderRadius:3,padding:'2px 6px',fontWeight:700}}>LOYAL -10% discount eligible</span>}</div>);})()}
