  // ═══ COMPARE MODAL ═══
  const CompareModal=({a,b,onClose})=>{if(!a||!b)return null;const rows=[['OVR','ovr'],['POT','pot'],['SPD','spd'],['STR','str'],['AGI','agi'],['ACC','acc'],['JMP','jmp'],['END','end'],['CONF','conf'],['AV','av'],['AGE','age'],['$M','salary']];return(<div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.9)",zIndex:1002,display:"flex",alignItems:"center",justifyContent:"center",padding:12}} onClick={onClose}><div onClick={e=>e.stopPropagation()} style={{background:C.cd,borderRadius:12,padding:14,maxWidth:480,width:"100%",border:`1px solid #7c3aed`,maxHeight:"85vh",overflowY:"auto"}}><div style={{fontSize:13,fontWeight:800,color:"#a78bfa",marginBottom:10,textAlign:"center"}}>⚖ PLAYER COMPARISON</div><div style={{display:"grid",gridTemplateColumns:"1fr 80px 1fr",gap:4,marginBottom:8}}><div style={{textAlign:"center"}}><Face s={a.face} sz={36}/><div style={{fontSize:13,fontWeight:800,marginTop:3}}>{a.name}</div><div style={{fontSize:11,color:C.mt}}>{a.pos} • {a.age}yr</div></div><div/><div style={{textAlign:"center"}}><Face s={b.face} sz={36}/><div style={{fontSize:13,fontWeight:800,marginTop:3}}>{b.name}</div><div style={{fontSize:11,color:C.mt}}>{b.pos} • {b.age}yr</div></div></div>{rows.map(([lbl,k])=>{const av=a[k]||0,bv=b[k]||0;const aBetter=av>bv,bBetter=bv>av;return(<div key={k} style={{display:"grid",gridTemplateColumns:"1fr 60px 1fr",gap:4,marginBottom:3,alignItems:"center"}}><div style={{textAlign:"right",fontWeight:aBetter?800:400,color:aBetter?C.gn:bBetter?C.rd:"#94a3b8",fontSize:13}}>{typeof av==="number"&&k==="salary"?`$${av.toFixed(1)}M`:av}</div><div style={{textAlign:"center",fontSize:10,color:C.mt,fontWeight:700}}>{lbl}</div><div style={{textAlign:"left",fontWeight:bBetter?800:400,color:bBetter?C.gn:aBetter?C.rd:"#94a3b8",fontSize:13}}>{typeof bv==="number"&&k==="salary"?`$${bv.toFixed(1)}M`:bv}</div></div>);})}  <Btn onClick={onClose} bg={C.bd} style={{width:"100%",marginTop:8}}>Close</Btn></div></div>);};
  // ═══ BOX SCORE MODAL ═══
