        const first={preseason:{label:"Training Camp",t:"roster",sub:"Camp work and mini games to improve your roster before the season",onClick:()=>go("roster","camp")},regular:{label:"Schedule",t:"schedule",sub:"Your games, this week's game plan and the playoff picture",onClick:()=>go("schedule")},playoffs:{label:"Playoff Bracket",t:"playoffs",sub:"The road to the Super Bowl",onClick:()=>go("playoffs")},combine:{label:"Scouting",t:"scouting",sub:"Combine results, interviews and your big board",onClick:()=>go("scouting")},resign:{label:"Re-sign Players",t:"freeagency",sub:"Only you can talk to your expiring players this week",onClick:()=>go("freeagency")},freeagency:{label:"Free Agency",t:"freeagency",sub:"Negotiate with the players on the market",onClick:()=>go("freeagency")},draft:{label:"NFL Draft",t:"draft",sub:"Make your picks",onClick:()=>go("draft")}}[sp];
        const rest=[...(dlShown?[["⏰ Trade Deadline Day","deadline"]]:[]),["Schedule+","schedule"],["Roster+","roster"],["Draft+",sp==="draft"?"draft":"scouting"],["Trades","trade"],["Free Agency","freeagency"],["Manage Staff","coaching"],["League+","hub"],["Trophy Room","trophies"],["Log","log"],["Game Info","gameinfo"],...(liveSim&&!liveDone?[["⚡ Live Game","livesim"]]:[])].map(([label,t])=>({label,t,onClick:()=>go(t,t==="roster"?"players":null)}));
        const menu=[...(first?[first]:[]),...rest.filter(m=>m.label!==first?.label&&!(first&&first.t===m.t&&m.t!=="roster"))];
        const primary=[];
        if(liveSim&&!liveDone)primary.push({label:"● Back to the live game",onClick:()=>setTab("livesim")});
        else if(sp==="preseason")primary.push({label:"Start Season",onClick:startSeason});
        else if(sp==="regular"&&dlActive)primary.push({label:"⏰ Go to Trade Deadline Day",onClick:()=>setTab("deadline")});
        else if(sp==="regular"){if(_ng)primary.push({label:`▶ Play Week ${wk+1}`,onClick:()=>startLiveSim(_ng)});primary.push({label:_ng?"Sim Week":"Advance Week",onClick:simWk});if(wk<TRADE_DEADLINE_WEEK)primary.push({label:"Sim to Deadline",onClick:()=>simAll(TRADE_DEADLINE_WEEK)});}
        else if(sp==="playoffs"&&pb){const m=pb.ch==null&&pb.m.find(([h,a])=>h===ui||a===ui);if(m)primary.push({label:`▶ Play ${ROUND_NAMES[pb.rd]}`,onClick:()=>startLiveSim({wk:`P${pb.rd}`,h:m[0],a:m[1],playoff:true})});primary.push(pb.ch==null?{label:`Sim ${ROUND_NAMES[pb.rd]}`,onClick:()=>simPR()}:{label:"→ Combine",onClick:goToCombine});}
        else if(sp==="combine")primary.push({label:"→ Re-sign Week",onClick:startResign});
        else if(sp==="resign")primary.push({label:"→ Free Agency",onClick:startFreeAgency});
        else if(sp==="freeagency")primary.push(draftPicks.length>0&&draftIdx>=draftPicks.length?{label:"→ Next Season",onClick:newSeason}:{label:"→ Draft",onClick:leaveFreeAgency});
        else if(sp==="draft")primary.push(draftActive?{label:"Go to the draft",onClick:()=>go("draft")}:{label:"→ Next Season",onClick:newSeason});
