      {sp==="regular"&&(()=>{const nug=sched.find(g=>!g.played&&(g.h===ui||g.a===ui));if(!nug)return null;const soid=nug.h===ui?nug.a:nug.h;const so=teams[soid];if(!so)return null;const soff=so.roster.filter(p=>['QB','RB','WR','TE'].includes(p.pos)&&!p.injured).sort((a,b)=>b.ovr-a.ovr)[0];const sdef=so.roster.filter(p=>['DL','LB','CB','S'].includes(p.pos)&&!p.injured).sort((a,b)=>b.ovr-a.ovr)[0];const sgames=sched.filter(g=>g.played&&(g.h===soid||g.a===soid));const avgPF=sgames.length?Math.round(sgames.reduce((s,g)=>s+(g.h===soid?g.hs:g.as),0)/sgames.length):'-';const avgPA=sgames.length?Math.round(sgames.reduce((s,g)=>s+(g.h===soid?g.as:g.hs),0)/sgames.length):'-';const runPct=Math.round(schemeRunPct(so)*100);return(<div style={{background:C.cd,border:`1px solid #d97706`,borderRadius:5,padding:"6px 8px",marginBottom:8}}><div style={{fontSize:12,fontWeight:700,color:C.gd,marginBottom:4}}>SCOUTING REPORT — WK {nug.wk} vs {so.city} {so.name}</div><div style={{display:"flex",gap:12,flexWrap:"wrap",fontSize:12}}><div><span style={{color:C.mt}}>Record </span><span style={{fontWeight:700,color:"#e2e8f0"}}>{so.w}-{so.l}</span>  <span style={{color:C.mt}}>PF/G </span><span style={{color:C.gn}}>{avgPF}</span>  <span style={{color:C.mt}}>PA/G </span><span style={{color:C.rd}}>{avgPA}</span></div><div><span style={{color:C.mt}}>OFF </span><span style={{fontWeight:700,color:"#e2e8f0"}}>{so.coach?.oc?.scheme||'Balanced'}</span><span style={{color:C.mt}}> {runPct}% run</span>{soff&&<><span style={{color:C.mt}}> • </span><span style={{color:"#e2e8f0"}}>{soff.name} <span style={{color:oC(soff.ovr)}}>{soff.pos} {soff.ovr}</span></span></>}</div><div><span style={{color:C.mt}}>DEF </span><span style={{fontWeight:700,color:"#e2e8f0"}}>{so.coach?.dc?.scheme||'4-3'}</span>{sdef&&<><span style={{color:C.mt}}> • </span><span style={{color:"#e2e8f0"}}>{sdef.name} <span style={{color:oC(sdef.ovr)}}>{sdef.pos} {sdef.ovr}</span></span></>}</div></div></div>);})()}
