        {!(sp==="draft"&&!draftActive&&draftLog.length)&&<div style={{display:'flex',gap:6,marginBottom:8}}>{[['board','Big Board'],['mock','Mock Draft']].map(([k,l])=><button key={k} onClick={()=>setDraftView(k)} style={{background:draftView===k?C.bl+'33':'transparent',color:draftView===k?'#fff':C.mt,border:`1px solid ${draftView===k?C.bl:C.bd}`,padding:'7px 16px',borderRadius:6,fontSize:15,fontWeight:700,cursor:'pointer'}}>{l}</button>)}</div>}
        {draftView==='mock'&&!(sp==="draft"&&!draftActive&&draftLog.length)?<MockDraft g={scoutG}/>:sp==="draft"&&draftActive&&curPick?<Board g={scoutG} classYr={yr} fixedYr onDraft={makePick} canDraft={curPick.owner===ui} title="Best available" page={30}/>:<Board g={scoutG} classYr={yr} title={sp==="draft"&&!draftActive&&draftLog.length?"Still on the board":`${yr} Big Board`}/>}
