      {draftClassRating&&(()=>{const dcrCol={Weak:'#ef4444',Average:'#eab308',Strong:'#22c55e',Elite:'#f59e0b'}[draftClassRating]||'#94a3b8';return(<div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6,padding:"4px 8px",background:dcrCol+'22',borderRadius:5,border:'1px solid '+dcrCol+'44'}}><span style={{fontSize:12,fontWeight:700,color:dcrCol}}>Draft Class: {draftClassRating}</span></div>);})()}
      {(()=>{const _posOrder=['QB','RB','WR','TE','LT','DL','LB','CB','S','K'];const _lgAvg={QB:82,RB:78,WR:80,TE:76,LT:80,DL:77,LB:76,CB:78,S:75,K:72};const _needs=_posOrder.map(pos=>{const _starters=(ut?.roster||[]).filter(p=>p.pos===pos&&!p.injSev);const _topOvr=_starters.length?Math.max(..._starters.map(p=>p.ovr||0)):0;const _gap=(_lgAvg[pos]||75)-_topOvr;return{pos,gap:_gap,grade:_gap>8?'F':_gap>4?'D':_gap>0?'C':_gap>-4?'B':'A'};}).sort((a,b)=>b.gap-a.gap);return <div style={{marginBottom:8,padding:'6px 8px',background:'#0a0f1a',border:'1px solid #1e293b',borderRadius:4}}><div style={{fontSize:10,color:'#334155',letterSpacing:2,marginBottom:4}}>POSITIONAL NEEDS</div><div style={{display:'flex',flexWrap:'wrap',gap:3}}>{_needs.map(n=>{const _col=n.grade==='F'?'#ef4444':n.grade==='D'?'#f97316':n.grade==='C'?'#f59e0b':n.grade==='B'?'#60a5fa':'#22c55e';return <div key={n.pos} style={{background:'#0d1424',border:`1px solid ${_col}`,borderRadius:3,padding:'2px 6px',display:'flex',gap:4,alignItems:'center'}}><span style={{fontSize:11,color:'#94a3b8'}}>{n.pos}</span><span style={{fontSize:12,fontWeight:'bold',color:_col}}>{n.grade}</span></div>;})}</div></div>;})()}
