    const FitBar=({val,max=4})=>{const pct=Math.round((val/max)*100);return<div style={{display:"flex",alignItems:"center",gap:4}}><div style={{flex:1,height:4,background:C.bd,borderRadius:2}}><div style={{width:`${pct}%`,height:"100%",background:val>=3?C.gn:val>=1.5?C.gd:C.rd,borderRadius:2}}/></div><span style={{fontSize:11,color:C.mt,minWidth:20}}>{val.toFixed(1)}</span></div>;};
